window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d0c5d4411ce2faac"]={"versions": [{"id": "FIG-d0c5d4411ce2faac", "releases": ["R2.1.20", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm zur Definition eines AUTOSAR-Metamodell-Stereotyps im Kontext des Template Modeling Guide (M2-Metamodellebene). Das Diagramm spezifiziert die Erweiterung einer UML-Standard-Metaklasse durch ein dediziertes Profil-Stereotyp.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Kernel::Constraint</code>: UML-Metaklasse (gekennzeichnet durch das Stereotyp <code>«metaclass»</code>), spezialisiert bzw. typisiert als <code>PackagableElement</code>. Dient als Ziel der Metaklassenerweiterung.\n</li><li><code>atpConstraint</code>: Definiertes Profil-Stereotyp, das zur Auszeichnung von Modell-Constraints dient.\n</li><li>Erweiterungsbeziehung (<code>«extends»</code>): Gerichtete Extension-Assoziation vom Stereotyp <code>atpConstraint</code> zur Metaklasse <code>Kernel::Constraint</code>, versehen mit der Eigenschaft bzw. dem Tag <code>{required}</code>, wodurch die Anwendung des Stereotyps auf Instanzen der erweiterten Metaklasse als verpflichtend deklariert ist.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Profildiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert die statische Bindung und Gültigkeitsregel für das Anwenden des Stereotyps <code>atpConstraint</code> auf <code>Constraint</code>-Elemente im Metamodell.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-M2-Metamodellierungs-Werkzeuge und Modellierer. Durch die Extension-Beziehung mit <code>{required}</code> muss jedes Modellierungs-Element vom Typ <code>Kernel::Constraint</code> im entsprechenden Metamodell-Kontext zwingend mit dem Stereotyp <code>atpConstraint</code> annotiert sein.</p>"}, {"id": "FIG-1df7a89a5487d969", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm zur Definition eines AUTOSAR-Metamodell-Stereotyps im Kontext des Template Modeling Guide (M2-Metamodellebene). Das Diagramm spezifiziert die Erweiterung einer UML-Standard-Metaklasse durch ein dediziertes Profil-Stereotyp.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Kernel::Constraint</code>: UML-Metaklasse (gekennzeichnet durch das Stereotyp <code>«metaclass»</code>), spezialisiert bzw. typisiert als <code>PackagableElement</code>. Dient als Ziel der Metaklassenerweiterung.\n</li><li><code>atpConstraint</code>: Definiertes Profil-Stereotyp, das zur Auszeichnung von Modell-Constraints dient.\n</li><li>Erweiterungsbeziehung (<code>«extends»</code>): Gerichtete Extension-Assoziation vom Stereotyp <code>atpConstraint</code> zur Metaklasse <code>Kernel::Constraint</code>, versehen mit der Eigenschaft bzw. dem Tag <code>{required}</code>, wodurch die Anwendung des Stereotyps auf Instanzen der erweiterten Metaklasse als verpflichtend deklariert ist.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Profildiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert die statische Bindung und Gültigkeitsregel für das Anwenden des Stereotyps <code>atpConstraint</code> auf <code>Constraint</code>-Elemente im Metamodell.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-M2-Metamodellierungs-Werkzeuge und Modellierer. Durch die Extension-Beziehung mit <code>{required}</code> muss jedes Modellierungs-Element vom Typ <code>Kernel::Constraint</code> im entsprechenden Metamodell-Kontext zwingend mit dem Stereotyp <code>atpConstraint</code> annotiert sein.</p>"}, {"id": "FIG-c326bdde813ce240", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm zur Definition eines AUTOSAR-Metamodell-Stereotyps im Kontext des Template Modeling Guide (M2-Metamodellebene). Das Diagramm spezifiziert die Erweiterung einer UML-Standard-Metaklasse durch ein dediziertes Profil-Stereotyp.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Kernel::Constraint</code>: UML-Metaklasse (gekennzeichnet durch das Stereotyp <code>«metaclass»</code>), spezialisiert bzw. typisiert als <code>PackagableElement</code>. Dient als Ziel der Metaklassenerweiterung.\n</li><li><code>atpConstraint</code>: Definiertes Profil-Stereotyp, das zur Auszeichnung von Modell-Constraints dient.\n</li><li>Erweiterungsbeziehung (<code>«extends»</code>): Gerichtete Extension-Assoziation vom Stereotyp <code>atpConstraint</code> zur Metaklasse <code>Kernel::Constraint</code>, versehen mit der Eigenschaft bzw. dem Tag <code>{required}</code>, wodurch die Anwendung des Stereotyps auf Instanzen der erweiterten Metaklasse als verpflichtend deklariert ist.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Profildiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert die statische Bindung und Gültigkeitsregel für das Anwenden des Stereotyps <code>atpConstraint</code> auf <code>Constraint</code>-Elemente im Metamodell.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-M2-Metamodellierungs-Werkzeuge und Modellierer. Durch die Extension-Beziehung mit <code>{required}</code> muss jedes Modellierungs-Element vom Typ <code>Kernel::Constraint</code> im entsprechenden Metamodell-Kontext zwingend mit dem Stereotyp <code>atpConstraint</code> annotiert sein.</p>"}], "trans": [{"from": "FIG-d0c5d4411ce2faac", "to": "FIG-1df7a89a5487d969", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1df7a89a5487d969", "to": "FIG-c326bdde813ce240", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c326bdde813ce240", "to": "FIG-d0c5d4411ce2faac", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
